export async function beforeInstall(ctx) {
  await ctx.registerCheckpoints([
    { "id": "validateContext", "message": "Validating install context" },
    { "id": "validateInline", "message": "Confirming inline execution" }
  ]);

  if (ctx.resourceType !== "app") throw new Error(`Wrong resourceType: ${ctx.resourceType}`);
  if (ctx.resourceId !== "hexos-test-inline") throw new Error(`Wrong resourceId: ${ctx.resourceId}`);
  if (ctx.event !== "onBeforeInstall") throw new Error(`Wrong event: ${ctx.event}`);
  await ctx.emitCheckpoint("validateContext");

  ctx.log("Inline hook running — no external .ts file needed");
  await ctx.emitCheckpoint("validateInline");
}

export async function afterInstall(ctx) {
  await ctx.registerCheckpoints([
    { "id": "appReachable", "message": "Waiting for app to start" },
    { "id": "healthCheck", "message": "Running health check" },
    { "id": "complete", "message": "Inline hook complete" }
  ]);

  await ctx.waitForApp("/");
  await ctx.emitCheckpoint("appReachable");

  const resp = await fetch(`${ctx.baseUrl}/health`, {
    signal: AbortSignal.timeout(5000)
  });
  ctx.log(`Health check: ${resp.status}`);
  await ctx.emitCheckpoint("healthCheck", `Health responded ${resp.status}`);

  await ctx.emitCheckpoint("complete", "All inline checks passed");
}

export async function optionalFail(ctx) {
  await ctx.registerCheckpoints([
    { "id": "willFail", "message": "About to fail intentionally" }
  ]);

  await ctx.updateCheckpointMessage("willFail", "Failing now...");
  ctx.log("Inline hook intentionally fails");
  throw new Error("Intentional inline failure for testing optional hook behavior");
}
